/**
 * ============================================================================
 * EXPERIMENT: assembler eviction — how to WEIGHT the incoming signals
 * ============================================================================
 *
 * Isolates the cache-assembler/ejector. One variable: the weights on the signals
 * the eviction score combines. Everything upstream held fixed (units = turns,
 * fingerprints deterministic). OFFLINE, no model — keep-needed recall is a
 * fingerprint fact, so every (turn × past-unit) pair is a datapoint (high power).
 *
 * THE NON-DEGENERACY RULE (why this measures anything): the assembler evicts at
 * t−1 using ONLY turns 0..t−1, to prepare for turn t which it cannot see. So
 * "relevance" is to the RECENT window, and "needed" is the FUTURE turn t. A unit
 * dormant in the recent window but referenced again at t (non-monotonic return,
 * H1) is the case that decides the weights — recency/recent-relevance drop it,
 * PRIORITY keeps it.
 *
 * SIGNALS for unit u at eviction-point t (all from 0..t−1), min-max normalized:
 *   rec     recency      = newer unit (1 − ageN)
 *   rel     relevance    = fingerprint Jaccard(u, union of last K turns)
 *   prio    priority     = # times u's fingerprint has recurred so far
 *   refrec  ref-recency  = recently referenced (1 − dormancyN); inverse of dormancy
 * score = w_rec·rec + w_rel·rel + w_prio·prio + w_refrec·refrec ; keep top-M + pinned.
 *
 * GROUND TRUTH: needed(u,t) = fingerprint(u) ∩ fingerprint(t) ≠ ∅ (referenced at t);
 *   horizon variant: referenced within [t, t+H).
 * METRIC: keep-needed recall @ budget M (task-critical), and separately on the
 *   NON-MONOTONIC subset (needed AND dormant > D turns). Occupancy = M (token proxy).
 *   Asymmetric by the operator's rule: dropping-needed is the failure; keeping-extra is cheap.
 *
 * PRE-REGISTERED: a signal EARNS its weight iff adding it lifts keep-needed recall
 *   (esp. non-monotonic) over the recency-only baseline by >=0.03 at equal M.
 *
 * RERUN: node experiments/assembler-weighting/assembler-weighting.mjs [--session 2]
 * ============================================================================
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { writeResults, gitSha, nowISO, REPO } from '../rung-1-live-probe/lib.mjs';

const argv = process.argv.slice(2);
const SESSION_N = argv.includes('--session') ? argv[argv.indexOf('--session') + 1] : '2';
const SESSION = join(REPO, `packages/cli/test/fixtures/claude-code-session${SESSION_N === '1' ? '' : '-2'}.jsonl`);
const K_RECENT = 5, H = 3, D_DORMANT = 10, START = 20;
const M_LIST = [8, 16, 32, 64];

// ---- fingerprints per turn ----
const RX = { path: /[\w-]+(?:\/[\w.-]+)*\.[a-z]{1,5}\b/gi, back: /`([^`]+)`/g, camel: /\b[a-z][a-zA-Z0-9]*[A-Z][a-zA-Z0-9]*\b/g, pascal: /\b[A-Z][a-z]+(?:[A-Z][a-z]+)+\b/g, upper: /\b[A-Z][A-Z0-9_]{3,}\b/g };
function fingerprint(text) {
  const fp = new Set();
  for (const m of text.matchAll(RX.path)) fp.add(m[0].toLowerCase());
  for (const m of text.matchAll(RX.back)) if (m[1].length >= 3 && m[1].length < 40) fp.add(m[1]);
  for (const rx of [RX.camel, RX.pascal, RX.upper]) for (const m of text.matchAll(rx)) fp.add(m[0]);
  return fp;
}
function parse() {
  const lines = readFileSync(SESSION, 'utf8').split('\n').filter(Boolean);
  const byId = {}; const turns = [];
  for (const l of lines) {
    let e; try { e = JSON.parse(l); } catch { continue; }
    if (e.type !== 'user' && e.type !== 'assistant') continue;
    const arr = Array.isArray(e.message?.content) ? e.message.content : [];
    let text = '';
    if (e.type === 'assistant') {
      text = arr.filter((b) => b.type === 'text').map((b) => b.text).join(' ');
      for (const b of arr) if (b.type === 'tool_use') { if (b.id) byId[b.id] = b.name; text += ' ' + (b.input?.file_path || '') + ' ' + JSON.stringify(b.input || {}).slice(0, 800); }
    } else {
      const tr = arr.find((b) => b.type === 'tool_result');
      if (tr) { let o = tr.content; if (Array.isArray(o)) o = o.map((x) => x.text || '').join(''); text = String(o || '').slice(0, 800); }
      else text = (typeof e.message.content === 'string' ? e.message.content : arr.filter((b) => b.type === 'text').map((b) => b.text).join(' ')).slice(0, 800);
    }
    const fp = fingerprint(text);
    if (!text.trim() && fp.size === 0) continue; // drop empty thinking-wrapper turns
    turns.push({ i: turns.length, fp });
  }
  return turns;
}
const overlap = (a, b) => { for (const x of a) if (b.has(x)) return true; return false; };

function main() {
  const turns = parse();
  const T = turns.length;
  const cand = turns.filter((t) => t.fp.size > 0).map((t) => t.i); // fingerprinted units
  // refs[u] = sorted turns r>u whose fingerprint overlaps u's
  const refs = {};
  for (const u of cand) { const r = []; for (let j = u + 1; j < T; j++) if (overlap(turns[u].fp, turns[j].fp)) r.push(j); refs[u] = r; }
  // union of last K fingerprints, per t
  const unionRecent = (t) => { const s = new Set(); for (let r = Math.max(0, t - K_RECENT); r < t; r++) for (const x of turns[r].fp) s.add(x); return s; };
  const jacc = (a, b) => { let inter = 0; for (const x of a) if (b.has(x)) inter++; return inter / (a.size + b.size - inter || 1); };
  const upTo = (arr, t) => { let lo = 0, hi = arr.length; while (lo < hi) { const m = (lo + hi) >> 1; if (arr[m] < t) lo = m + 1; else hi = m; } return lo; }; // count < t

  // weighting arms: [w_rec, w_rel, w_prio, w_refrec]
  const NAMED = {
    'recency-only': [1, 0, 0, 0], 'relevance-only': [0, 1, 0, 0], 'priority-only': [0, 0, 1, 0],
    'rel+prio': [0, 1, 1, 0], 'rel+prio+refrec': [0, 1, 1, 1], 'rec+rel+prio+refrec': [0.5, 1, 1, 1],
  };
  const grid = {};
  for (const wrel of [0, 0.5, 1]) for (const wprio of [0, 0.5, 1]) for (const wrefrec of [0, 0.5, 1]) for (const wrec of [0, 0.5, 1]) {
    if (wrel + wprio + wrefrec + wrec === 0) continue;
    grid[`g_${wrec}_${wrel}_${wprio}_${wrefrec}`] = [wrec, wrel, wprio, wrefrec];
  }
  const ARMS = { ...NAMED, ...grid };

  // accumulate recall per arm per M
  const acc = {}; for (const a of Object.keys(ARMS)) acc[a] = Object.fromEntries(M_LIST.map((M) => [M, { hit: 0, need: 0, nmHit: 0, nmNeed: 0 }]));
