  }));
  const base = rows['recency-only'];
  const named = Object.fromEntries(Object.keys(NAMED).map((a) => [a, rows[a]]));
  // best grid weighting per M by recall
  const bestByM = Object.fromEntries(M_LIST.map((M) => {
