1	/**
2	 * Faithful OpenAI tool-calling agentic loop against the LOCAL model.
3	 *
4	 * The local server round-trips native `tool_calls` (verified), so we use the
5	 * OpenAI message format on both sides — assistant messages with `tool_calls` are
6	 * appended VERBATIM, tool results come back as {role:"tool", tool_call_id}. This
7	 * makes the S4 trap (a bespoke ChatMessage that can't represent a tool call)
8	 * structurally impossible: the server owns the representation, not us.
9	 *
10	 * Tools run in a temp working dir; run_bash is whitelisted for safety.
11	 */
12	import { execSync } from 'node:child_process';
13	import { mkdtempSync, readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
14	import { tmpdir } from 'node:os';
15	import { join, dirname } from 'node:path';
16	
17	export const BASE_URL = process.env.CT_LOCAL_BASE_URL || 'http://127.0.0.1:8888/v1';
18	export const MODEL = process.env.CT_LOCAL_MODEL || 'unsloth/Qwen3.8-27B-GGUF';
19	export const API_KEY = process.env.UNSLOTH_API_KEY || 'sk-unsloth-YOUR_KEY';
20	
21	export const TOOL_SCHEMAS = [
22	  { type: 'function', function: { name: 'read_file', description: 'Read a file in the workspace.', parameters: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } } },
23	  { type: 'function', function: { name: 'write_file', description: 'Create or overwrite a file in the workspace.', parameters: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'] } } },
24	  { type: 'function', function: { name: 'edit_file', description: 'Replace the first occurrence of old_str with new_str in a file.', parameters: { type: 'object', properties: { path: { type: 'string' }, old_str: { type: 'string' }, new_str: { type: 'string' } }, required: ['path', 'old_str', 'new_str'] } } },
25	  { type: 'function', function: { name: 'list_files', description: 'List files in the workspace.', parameters: { type: 'object', properties: {} } } },
26	  { type: 'function', function: { name: 'run_bash', description: 'Run a shell command in the workspace. Allowed: python3, python, pytest, ls, cat, echo, pwd, mkdir, head, tail, grep, find.', parameters: { type: 'object', properties: { command: { type: 'string' } }, required: ['command'] } } },
27	];
28	
29	const BASH_WHITELIST = ['python3', 'python', 'pytest', 'ls', 'cat', 'echo', 'pwd', 'mkdir', 'head', 'tail', 'grep', 'find'];
30	const clip = (s, n = 2000) => (s && s.length > n ? s.slice(0, n) + `\n…[${s.length} chars truncated]` : (s || ''));
31	
32	export function makeWorkspace() { return mkdtempSync(join(tmpdir(), 'ct-code-')); }
33	
34	export function execTool(ws, name, args) {
35	  try {
36	    if (name === 'read_file') { const p = join(ws, args.path); return existsSync(p) ? clip(readFileSync(p, 'utf8')) : `error: no such file ${args.path}`; }
37	    if (name === 'write_file') { const p = join(ws, args.path); mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, args.content ?? ''); return `wrote ${args.path} (${(args.content ?? '').length} bytes)`; }
38	    if (name === 'edit_file') { const p = join(ws, args.path); if (!existsSync(p)) return `error: no such file ${args.path}`; const t = readFileSync(p, 'utf8'); if (!t.includes(args.old_str)) return `error: old_str not found in ${args.path}`; writeFileSync(p, t.replace(args.old_str, args.new_str)); return `edited ${args.path}`; }
39	    if (name === 'list_files') { return clip(execSync(`find . -type f -not -path '*/.*'`, { cwd: ws }).toString()); }
40	    if (name === 'run_bash') {
41	      const cmd = String(args.command || ''); const head = cmd.trim().split(/\s+/)[0];
42	      if (!BASH_WHITELIST.includes(head)) return `error: command '${head}' not allowed. Allowed: ${BASH_WHITELIST.join(', ')}`;
43	      try { return clip(execSync(cmd, { cwd: ws, timeout: 30000, stdio: ['ignore', 'pipe', 'pipe'] }).toString() || '(no output)'); }
44	      catch (e) { return clip(`exit ${e.status ?? '?'}\nstdout:\n${e.stdout?.toString() || ''}\nstderr:\n${e.stderr?.toString() || ''}`); }
45	    }
46	    return `error: unknown tool ${name}`;
47	  } catch (e) { return `error executing ${name}: ${e.message}`; }
48	}
49	
50	async function callModel(messages, { think = false, maxTokens = 1024 }) {
51	  const res = await fetch(`${BASE_URL}/chat/completions`, {
52	    method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${API_KEY}` },
53	    body: JSON.stringify({ model: MODEL, messages, tools: TOOL_SCHEMAS, tool_choice: 'auto', parallel_tool_calls: false, max_tokens: maxTokens, temperature: 0, chat_template_kwargs: { enable_thinking: think } }),
54	  });
55	  if (!res.ok) throw new Error(`HTTP ${res.status}: ${(await res.text()).slice(0, 300)}`);
56	  return res.json();
57	}
58	
59	// ===================== eviction (the assembler under test) =====================
60	export const estTokens = (msgs) => Math.ceil(msgs.reduce((s, m) => s + (m.content || '').length + JSON.stringify(m.tool_calls || '').length, 0) / 4);
61	const ANCHOR = +(process.env.CT_ANCHOR || 4); // recency anchor: # most-recent units eviction never drops (working set)
62	
63	/**
64	 * Split the message array into pinned head (system + first user task) + UNITS.
65	 * A unit is a coherent slice that keeps tool-call validity: an assistant message
66	 * with tool_calls travels WITH all its following tool results, so eviction can
67	 * never orphan a call from its result (the S4/format trap for eviction).
68	 */
69	export function extractUnits(messages) {
70	  const pinned = messages.slice(0, 2); // [system, first user task]
71	  const units = []; let i = 2;
72	  while (i < messages.length) {
73	    const start = i; const m = messages[i];
74	    if (m.role === 'assistant' && m.tool_calls?.length) { i++; while (i < messages.length && messages[i].role === 'tool') i++; }
75	    else i++;
76	    const slice = messages.slice(start, i);
77	    const files = new Set(); let blob = '';
78	    for (const mm of slice) { blob += ' ' + (mm.content || ''); for (const tc of mm.tool_calls || []) { blob += ' ' + (tc.function.arguments || ''); try { const a = JSON.parse(tc.function.arguments || '{}'); if (a.path) files.add(a.path); } catch {} } }
79	    // fingerprint = paths + DISTINCTIVE identifiers (snake_case fns, filenames, CamelCase) so a unit
80	    // that references another's symbols (e.g. a module importing parse_ts) co-references it.
81	    const fp = new Set(files);
82	    for (const m2 of blob.matchAll(/[A-Za-z_][A-Za-z0-9_.]{2,}/g)) { const t = m2[0]; if ((/_/.test(t) && t.length >= 5) || /\.[a-z]{1,4}$/.test(t) || /^[A-Z][a-z]+[A-Z]/.test(t)) fp.add(t); }
83	    units.push({ slice, files, fp, wrote: slice.some((mm) => (mm.tool_calls || []).some((tc) => /write_file|edit_file/.test(tc.function.name))) });
84	  }
85	  return { pinned, units };
86	}
87	
88	function rebuild(messages, pinned, keptUnits) {
89	  const next = [...pinned, ...keptUnits.flatMap((u) => u.slice)];
90	  messages.length = 0; messages.push(...next); // in-place (the hook mutates the live array)
91	}
92	
93	// Recency eviction: keep pinned + the most-recent units that fit the budget.
94	export function evictRecency(messages, budget, reserve = 512) {
95	  const { pinned, units } = extractUnits(messages);
96	  const avail = budget - estTokens(pinned) - reserve;
97	  if (avail <= 0 || estTokens(units.flatMap((u) => u.slice)) <= avail) return false;
98	  const kept = []; let used = 0;
99	  for (let k = units.length - 1; k >= 0; k--) { const t = estTokens(units[k].slice); if (used + t <= avail || kept.length < ANCHOR) { kept.unshift(units[k]); used += t; } else break; }
