/**
 * ============================================================================
 * EXPERIMENT: buried detail — where SUMMARIZE fails and CHUNK+RETRIEVE wins
 * ============================================================================
 * Solution #2 (summarize) broke the read-loop when the needed info survived
 * abstraction (docstrings). This tests the operator's hypothesis: when the needed
 * info is a BURIED DETAIL, summarization DROPS it and chunk+retrieve is required.
 *
 * One variable = the MIDDLEWARE reducer applied to the document read (tool.execute.after):
 *   none          — full doc returned (baseline; correct but heavy)
 *   summarize     — gist (headings + first lines): the buried number is dropped
 *   chunk_retrieve — the span most relevant to the task query, verbatim: number kept
 *
 * TASK: read a long spec whose body buries "the payments API rate limit is 137
 * requests per minute"; write ONLY that number to answer.txt. Success = answer.txt
 * contains 137. Everything else in the spec is filler, so the gist cannot answer.
 *
 * PREDICTION: none PASS (heavy), summarize FAIL (137 dropped), chunk_retrieve PASS
 * (137 kept, far fewer tokens). A null (summarize also passes) would falsify the
 * "summarization is insufficient for buried detail" claim.
 *
 * This is a MIDDLEWARE experiment: the reducer is the plugin's payload; the model
 * and loop are unchanged. RERUN: node experiments/coding-harness/buried-detail.mjs
 *   (CT_LOCAL_MODEL selects the local model; default is the configured one.)
 * ============================================================================
 */
import { execSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { runAgent, makeWorkspace, estTokens, MODEL } from './lib.mjs';
import { REDUCERS } from './reducers.mjs';
import { writeResults, gitSha, nowISO } from '../rung-1-live-probe/lib.mjs';

const SECRET = 137; // the buried detail
function makeSpec(ws) {
  const topics = ['Overview', 'Authentication', 'Accounts API', 'Ledger API', 'Webhooks', 'Payments API',
    'Refunds API', 'Idempotency', 'Errors', 'Pagination', 'Rate Limits', 'Sandbox', 'Versioning', 'Changelog'];
  const filler = (t) => `This section documents the ${t} surface. It covers request and response shapes, ` +
    `field semantics, and common integration patterns. Clients should follow the conventions described here ` +
    `and consult the reference for exhaustive field lists. Typical usage involves configuring credentials, ` +
    `issuing requests, and handling responses idempotently. See related sections for cross-cutting concerns.`;
  const lines = ['# Service Specification', ''];
  for (const t of topics) {
    lines.push(`## ${t}`, filler(t));
    if (t === 'Rate Limits') lines.push(`Per-endpoint limits apply. In particular, the payments API rate limit is ${SECRET} requests per minute; exceeding it returns HTTP 429.`);
    lines.push('');
  }
  writeFileSync(join(ws, 'spec.md'), lines.join('\n'));
}

const SYSTEM = 'You are an agent in a workspace. Use the tools to read files and run commands. Answer precisely and, when done, reply with a short message containing DONE and no tool call.';
const TASK = 'Read spec.md. Find the payments API rate limit (a number of requests per minute). Write ONLY that number (digits only) to answer.txt using write_file. Then reply DONE.';

async function runArm(name) {
  const ws = makeWorkspace();
  makeSpec(ws);
  let peak = 0;
  // Restrict tools to read_file + write_file: the document is reachable ONLY through the reducer's
  // path (no run_bash grep escape hatch), isolating the reducer's effect — as in forced window overflow.
  const r = await runAgent({ system: SYSTEM, task: TASK, ws, maxTurns: 16, think: false, reducer: REDUCERS[name], allowedTools: ['read_file', 'write_file'], hook: (m) => { peak = Math.max(peak, estTokens(m)); } });
  let answer = ''; try { answer = execSync('cat answer.txt', { cwd: ws, timeout: 5000 }).toString().trim(); } catch { answer = '(none)'; }
  const success = /\b137\b/.test(answer);
  const total = r.usage.reduce((s, u) => s + (u.prompt_tokens || 0), 0);
  return { reducer: name, success, answer: answer.slice(0, 40), turns: r.turns, stop: r.stop, peak_history_tokens: peak, total_prompt_tokens: total, reads: r.toolLog.filter((t) => t.name === 'read_file').length };
}

async function main() {
  const arms = [];
  for (const name of ['none', 'summarize', 'chunk_retrieve']) { console.error(`\n--- reducer: ${name} ---`); arms.push(await runArm(name)); }
  const out = {
    manifest: {
      run_id: `buried-detail-${Date.now()}`, experiment: 'coding-harness / buried-detail (summarize vs chunk)',
      model: MODEL, buried_value: SECRET, seam: 'middleware reducer at tool.execute.after (plugin payload)',
      commit: gitSha(), date: nowISO(),
      falsification: 'summarize is insufficient for buried detail IFF summarize FAILS while chunk_retrieve PASSES',
      caveats: ['n=1 per arm, temp 0 (deterministic). Single model/task.', 'Chunk retrieval is BM25-ish overlap vs the task string — a weak retriever; a real one is stronger.', 'Text-only; the PDF/vision version needs an image model.'],
    },
    arms,
  };
  const path = writeResults('coding-harness', 'results-buried-detail.json', out);
  console.error('\n=== BURIED DETAIL (reducer = one variable) ===  [success | answer | turns | reads | peakTok | totalPromptTok]');
  for (const a of arms) console.error(`  ${a.reducer.padEnd(14)} ${a.success ? 'PASS' : 'FAIL'}  ans=${JSON.stringify(a.answer)}  turns=${a.turns}  reads=${a.reads}  peak=${a.peak_history_tokens}  totalPrompt=${a.total_prompt_tokens}`);
  const s = Object.fromEntries(arms.map((a) => [a.reducer, a.success]));
  console.error(`\n  hypothesis (summarize insufficient, chunk needed): ${s.summarize === false && s.chunk_retrieve === true ? 'CONFIRMED' : 'not confirmed'}`);
  console.error(`  written: ${path}`);
}
main().catch((e) => { console.error('FATAL', e); process.exit(1); });

