    const fitsWindow = ctxTok < WINDOW - 256; // leave room for question+completion
    let answer = '', fits = fitsWindow, err = null, correct = false;
    if (!fitsWindow) { fits = false; err = `context ${ctxTok} tok exceeds window ${WINDOW}`; }
    else {
      try {
        const r = await generate({ system: SYSTEM, user: `Documents:\n"""\n${ctx}\n"""\n\n${QUESTION}`, maxTokens: 24, temperature: 0, think: false });
