      } catch (e) { fits = false; err = String(e.message || e).slice(0, 120); }
    }
    arms.push({ reducer: name, fits_window: fits, prices_present: pricesPresent, model_correct: correct, answer, ctx_tokens: ctxTok, error: err });
    process.stderr.write(`${name.padEnd(14)} fits=${fits} ctx_tok=${ctxTok} prices=${pricesPresent} correct=${correct} ans=${JSON.stringify(answer)}${err ? ' err=' + err : ''}\n`);
  }
  const out = {
    manifest: {
      run_id: `hard-window-${Date.now()}`, experiment: 'coding-harness / hard-window multi-doc synthesis (8.2K)',
      model: MODEL, window: WINDOW, n_docs: ITEMS.length, raw_total_tokens: rawTokens, correct_sum: TOTAL,
      seam: 'middleware reducer per document (plugin tool.execute.after payload)', commit: gitSha(), date: nowISO(),
      falsification: 'the middleware is required IFF raw+summarize FAIL (overflow / prices lost) while chunk_retrieve PASSES (fits + prices kept + answered)',
      caveats: ['n=1 per arm, temp 0. Low-quant 8.2K model — arithmetic may wobble; prices_present is the mechanism metric, the sum is arithmetic on top.', 'Chunk retrieval is a weak lexical proxy.', 'Text-only stand-in for the PDF/excel/report task.'],
    },
    arms,
  };
  const path = writeResults('coding-harness', 'results-hard-window-synthesis.json', out);
  console.error(`\n=== HARD-WINDOW SYNTHESIS (window ${WINDOW}, raw docs ~${rawTokens} tok) ===`);
  for (const a of arms) console.error(`  ${a.reducer.padEnd(14)} fits=${a.fits_window ? 'Y' : 'N'} prices_present=${a.prices_present} model_correct=${a.model_correct} ctx=${a.ctx_tokens}`);
  const s = Object.fromEntries(arms.map((a) => [a.reducer, a]));
  const confirmed = !s.raw.fits_window && s.summarize.model_correct === false && s.chunk_retrieve.model_correct === true;
  console.error(`\n  middleware REQUIRED under hard window: ${confirmed ? 'CONFIRMED' : 'not confirmed'}`);
  console.error(`  written: ${path}`);
