/**
 * ============================================================================
 * STRESS TEST: multi-doc synthesis under a REAL hard window (8.2K model)
 * ============================================================================
 * Stacks both failure modes under a genuine hardware ceiling (no simulated
 * budget): FOUR large documents (~2.5K tokens each, ~10K total >> 8192 window),
 * each BURYING one unit price needed for the final answer. Single-turn; the
 * middleware assembles the context; one variable = the reducer.
 *
 *   raw           — concat all docs (~10K tok) > 8192 window → the REQUEST ERRORS
 *                   (the hard wall: you cannot even send it). Demonstrates the constraint.
 *   summarize     — gist per doc: fits, but every buried price is DROPPED → model can't answer
 *   chunk_retrieve — the price span per doc, verbatim: fits AND keeps all 4 prices → model answers
 *
 * METRICS: fits_window (request accepted), prices_present (all 4 in the assembled
 *   context), model answer (contains the sum). The mechanism is prices_present;
 *   the sum is the model's arithmetic on top.
 *
 * PREDICTION: raw FAILS (overflow / can't send), summarize FAILS (prices lost),
 *   chunk_retrieve PASSES (fits + prices kept). Confirms the middleware is REQUIRED
 *   under a hard window to both fit AND preserve the answer.
 *
 * RERUN: CT_LOCAL_MODEL=unsloth/Qwen3.8-Flash-Next-GGUF \
 *        node experiments/coding-harness/hard-window-synthesis.mjs
 * ============================================================================
 */
import { generate, MODEL, writeResults, gitSha, nowISO, estTok } from '../rung-1-live-probe/lib.mjs';
import { REDUCERS } from './reducers.mjs';

const WINDOW = 8192;
const ITEMS = [{ name: 'Widget', price: 13 }, { name: 'Gadget', price: 27 }, { name: 'Gizmo', price: 41 }, { name: 'Doohickey', price: 58 }];
const TOTAL = ITEMS.reduce((s, i) => s + i.price, 0); // 139

function makeDoc(name, price) {
  const secs = ['Overview', 'Specifications', 'Materials', 'Assembly', 'Warranty', 'Compliance', 'Shipping',
    'Returns', 'Support', 'Compatibility', 'Maintenance', 'Safety', 'Packaging', 'History', 'Roadmap', 'FAQ'];
  const filler = (s) => `The ${s} section for the ${name} product line describes conventions, procedures, and ` +
    `expectations in detail. Integrators should review this material carefully and cross-reference the catalog ` +
    `for exhaustive parameters. Standard handling and configuration apply throughout, and exceptions are noted ` +
    `where relevant. This information is provided for completeness and does not change frequently between revisions.`;
  const lines = [`# ${name} Product Catalog`, ''];
  for (const s of secs) {
    lines.push(`## ${s}`, filler(s));
    if (s === 'Specifications') lines.push(`Pricing note: the ${name} unit price is ${price} dollars per unit (list price, ex-tax).`);
    lines.push('');
  }
  return lines.join('\n');
}

const SYSTEM = 'Answer using ONLY the provided documents. The four documents each state a unit price. Reply with only the integer sum of the four unit prices, or UNKNOWN if any price is missing.';
const QUESTION = 'Using the catalogs, what is the sum of the unit prices of the Widget, Gadget, Gizmo, and Doohickey (an integer)?';

async function main() {
  const docs = ITEMS.map((i) => makeDoc(i.name, i.price));
  const rawTokens = estTok(docs.join('\n\n'));
  const arms = [];
  for (const name of ['raw', 'summarize', 'chunk_retrieve']) {
    const reducer = name === 'raw' ? REDUCERS.none : REDUCERS[name];
    const ctx = docs.map((d) => reducer({ out: d, task: QUESTION })).join('\n\n---\n\n');
    const ctxTok = estTok(ctx);
    const pricesPresent = ITEMS.every((i) => new RegExp(`\\b${i.price}\\b`).test(ctx));
    const fitsWindow = ctxTok < WINDOW - 256; // leave room for question+completion
    let answer = '', fits = fitsWindow, err = null, correct = false;
    if (!fitsWindow) { fits = false; err = `context ${ctxTok} tok exceeds window ${WINDOW}`; }
    else {
      try {
        const r = await generate({ system: SYSTEM, user: `Documents:\n"""\n${ctx}\n"""\n\n${QUESTION}`, maxTokens: 24, temperature: 0, think: false });
        answer = (r.grade_text || '').slice(0, 40); correct = new RegExp(`\\b${TOTAL}\\b`).test(r.grade_text || '');
      } catch (e) { fits = false; err = String(e.message || e).slice(0, 120); }
    }
    arms.push({ reducer: name, fits_window: fits, prices_present: pricesPresent, model_correct: correct, answer, ctx_tokens: ctxTok, error: err });
    process.stderr.write(`${name.padEnd(14)} fits=${fits} ctx_tok=${ctxTok} prices=${pricesPresent} correct=${correct} ans=${JSON.stringify(answer)}${err ? ' err=' + err : ''}\n`);
  }
  const out = {
    manifest: {
      run_id: `hard-window-${Date.now()}`, experiment: 'coding-harness / hard-window multi-doc synthesis (8.2K)',
      model: MODEL, window: WINDOW, n_docs: ITEMS.length, raw_total_tokens: rawTokens, correct_sum: TOTAL,
      seam: 'middleware reducer per document (plugin tool.execute.after payload)', commit: gitSha(), date: nowISO(),
      falsification: 'the middleware is required IFF raw+summarize FAIL (overflow / prices lost) while chunk_retrieve PASSES (fits + prices kept + answered)',
      caveats: ['n=1 per arm, temp 0. Low-quant 8.2K model — arithmetic may wobble; prices_present is the mechanism metric, the sum is arithmetic on top.', 'Chunk retrieval is a weak lexical proxy.', 'Text-only stand-in for the PDF/excel/report task.'],
    },
    arms,
  };
  const path = writeResults('coding-harness', 'results-hard-window-synthesis.json', out);
  console.error(`\n=== HARD-WINDOW SYNTHESIS (window ${WINDOW}, raw docs ~${rawTokens} tok) ===`);
  for (const a of arms) console.error(`  ${a.reducer.padEnd(14)} fits=${a.fits_window ? 'Y' : 'N'} prices_present=${a.prices_present} model_correct=${a.model_correct} ctx=${a.ctx_tokens}`);
  const s = Object.fromEntries(arms.map((a) => [a.reducer, a]));
  const confirmed = !s.raw.fits_window && s.summarize.model_correct === false && s.chunk_retrieve.model_correct === true;
  console.error(`\n  middleware REQUIRED under hard window: ${confirmed ? 'CONFIRMED' : 'not confirmed'}`);
  console.error(`  written: ${path}`);
}
main().catch((e) => { console.error('FATAL', e); process.exit(1); });

